func memberRoleRevisionMigration(db *gorm.DB) error {
	for _, step := range []struct {
		model        any
		field, check string
	}{
		{&memberRoleUserV56{}, "MemberRoleRevision", "ck_users_member_role_revision"},
		{&memberRoleDefinitionV56{}, "DefinitionRevision", "ck_roles_definition_revision"},
	} {
		if !db.Migrator().HasColumn(step.model, step.field) {
			if err := db.Migrator().AddColumn(step.model, step.field); err != nil {
				return err
			}
		}
		// Repair only absent/blank partial-DDL baseline values. Preserve every
		// already chosen generation; malformed nonblank values fail the guard.
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(step.model); err != nil {
			return err
		}
		field := stmt.Schema.LookUpField(step.field)
		column := clause.Column{Name: field.DBName}
		if err := db.Session(&gorm.Session{NewDB: true}).Model(step.model).
			Where(clause.Or(clause.Eq{Column: column, Value: nil}, ExactText(db, column, ""))).
			UpdateColumn(step.field, strings.Repeat("0", 64)).Error; err != nil {
			return err
		}
		columns, err := db.Migrator().ColumnTypes(step.model)
		if err != nil {
			return err
		}
		found := false
		for _, c := range columns {
			if c.Name() != field.DBName {
				continue
			}
			found = true
			size, sized := c.Length()
			nullable, known := c.Nullable()
			def, defaulted := c.DefaultValue()
			if !sized || size != 64 || !known || nullable || !defaulted || !strings.Contains(def, strings.Repeat("0", 64)) {
				if err := db.Migrator().AlterColumn(step.model, step.field); err != nil {
					return err
				}
			}
		}
		if !found {
			return fmt.Errorf("role revision column is unavailable")
		}
		if !db.Migrator().HasConstraint(step.model, step.check) {
			if err := db.Migrator().CreateConstraint(step.model, step.check); err != nil {
				return err
			}
		}
	}
	return nil
}
